export function chapterThreeCombat({root,camera,free,blocked,rand=Math.random}){
 const shots=[],warnings=[];let time=0;
 const dispose=m=>{m.removeFromParent();m.geometry.dispose();m.material.dispose()};
 function clear(){for(const s of shots)dispose(s.m);for(const s of warnings)dispose(s.m);shots.length=warnings.length=0}
 function sight(n){const p=n.g.position.clone().setY(1.5);for(let t=.04;t<1;t+=.04)if(blocked(p.clone().lerp(camera.position,t)))return false;return true}
 function shoot(n,angle=0,damage=C3_STATS[n.role].damage){const arrow=['marksman','captain'].includes(n.role),from=n.g.position.clone().add(new T.Vector3(0,1.6,0)),v=camera.position.clone().sub(from).normalize().applyAxisAngle(new T.Vector3(0,1,0),angle).multiplyScalar(arrow?38:34);const m=new T.Mesh(arrow?new T.CylinderGeometry(.018,.018,.7,5):new T.IcosahedronGeometry(.2,1),new T.MeshBasicMaterial({color:arrow?0xe0c991:n.role==='gargoyle'?0xa5e9e9:0xb63163}));m.position.copy(from);root().add(m);shots.push({m,v,age:0,damage,arrow,owner:n.id,slow:['gargoyle','hag','abbess'].includes(n.role)?2:0})}
 function warn(pos,r,damage,owner){const m=new T.Mesh(new T.RingGeometry(r*.92,r,40),new T.MeshBasicMaterial({color:0xf24c78,side:T.DoubleSide,transparent:true,opacity:.8,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.copy(pos).setY(.07);root().add(m);warnings.push({m,age:0,r,damage,owner})}
 function tick(dt,mobs,{onDamage,onSlow=()=>{},onSound=()=>{},spawnAdds=()=>{}}){time+=dt;
  for(const n of mobs){if(n.hp<=0)continue;const step=statusStep(n,dt),ranged=n.flightLeft>0||['marksman','cantor','gargoyle','captain','hag','harpy','abbess','whelp'].includes(n.role),boss=['baron','abbess','ashwing'].includes(n.role),d=Math.hypot(n.g.position.x-camera.position.x,n.g.position.z-camera.position.z);for(const k of ['cooldown','special','block','blockReady'])n[k]=Math.max(0,(n[k]||0)-step);if(!n.aggro&&canSense(n,camera,d,boss?45:ranged?26:14)){n.aggro=camera.position.clone();if(n.role==='werewolf')onSound('werewolf-aggro')}if(n.role==='werewolf'&&n.aggro&&!n.aggroCue){n.aggroCue=true;onSound('werewolf-aggro')}if(!n.aggro)n.aggroCue=false;if(!boss&&n.aggro&&camera.position.distanceTo(n.aggro)>90)n.aggro=null;if(['whelp','ashwing'].includes(n.role)){n.flightReady=Math.max(0,(n.flightReady??8)-step);n.flightLeft=Math.max(0,(n.flightLeft||0)-dt);if(n.aggro&&!n.flightReady&&!n.flightLeft&&!n.stun&&!n.root){let goal;for(let j=0;j<16;j++){const angle=Math.atan2(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z)+(j%2?1:-1)*(1+j*.17),radius=d>18?Math.min(d-8,24):14;const q=n.g.position.clone().add(new T.Vector3(Math.sin(angle)*radius,0,Math.cos(angle)*radius));if(free(q.x,q.z,.8)){goal=q;break}}if(goal){n.flightLeft=8;n.flightReady=22;n.flightTarget=goal;onSound('dragon-wings')}}}

   if(boss&&n.aggro&&n.hp<n.maxHp*.5&&n.phase!==2){n.phase=2;n.block=0;if(!n.addsUsed){n.addsUsed=true;spawnAdds(n)}onSound('ice')}
   if(!step){n.update(0);continue}
   if(n.windup>0){n.windup=Math.max(0,n.windup-step);if(!n.windup&&n.aggro){if(n.pending==='breath'){const dir=camera.position.clone().sub(n.g.position).setY(0).normalize();for(const distance of [4,8,12,16])warn(n.g.position.clone().addScaledVector(dir,distance),3.4,36,n.id);onSound('fireball')}else if(n.pending==='scream'){if(d<15){onSlow(2.5);onDamage(18,'magic',n.id)}onSound('ghost-combat')}else if(n.pending==='tide'){for(const offset of [-2.5,0,2.5])warn(camera.position.clone().add(new T.Vector3(offset,0,0)),2.3,28,n.id);onSound('fireball')}else if(n.pending==='nova')warn(camera.position.clone(),4.5,30,n.id);else if(n.pending==='charge'){const dir=camera.position.clone().sub(n.g.position).setY(0).normalize();for(let j=0;j<20&&!n.root;j++){if(Math.hypot(n.g.position.x-camera.position.x,n.g.position.z-camera.position.z)<2.2)break;const x=n.g.position.x+dir.x*.55,z=n.g.position.z+dir.z*.55;if(!free(x,z,.6))break;n.g.position.set(x,0,z)}if(Math.hypot(n.g.position.x-camera.position.x,n.g.position.z-camera.position.z)<3.5){onDamage(boss?34:28,'physical',n.id);onSlow(1.5)}onSound('sword')}else if(n.pending==='heal'){for(const ally of mobs)if(ally!==n&&ally.hp>0&&ally.g.position.distanceTo(n.g.position)<10)ally.hp=Math.min(ally.maxHp,ally.hp+18);onSound('ice')}else if(ranged||boss&&d>3.4){const angles=boss?[-.16,0,.16]:n.role==='captain'?[-.09,0,.09]:[0];for(const angle of angles)shoot(n,angle,boss?23:C3_STATS[n.role].damage);onSound(['marksman','captain'].includes(n.role)?'bow':'fireball')}else if(d<3.5&&sight(n)){onDamage(C3_STATS[n.role].damage,'physical',n.id);onSound(['hound','werewolf'].includes(n.role)?'werewolf-hit':'sword')}}
   }else if(n.aggro){n.heading=Math.atan2(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z);if(!n.root){if(n.flightLeft>0&&n.flightTarget)steer(n,n.flightTarget,n.role==='ashwing'?7:6,step,free,()=>true,.5);else if(!ranged&&d>2.5)steer(n,camera.position,boss?(n.phase===2?4:3.1):['hound','werewolf'].includes(n.role)?4.1:2.9,step,free,()=>true,.5);else if(ranged){const dir=n.g.position.clone().sub(camera.position).setY(0).normalize(),goal=d>22?camera.position:d<8?n.g.position.clone().addScaledVector(dir,4):n.g.position.clone().add(new T.Vector3(Math.sin(time)*2,0,Math.cos(time)*2));steer(n,goal,2.2,step,free,()=>true,.4)}}n.heading=Math.atan2(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z);
    if(['knight','baron','sentinel'].includes(n.role)&&n.phase===1&&!n.blockReady){n.block=2.2;n.blockReady=8}
    if(!n.cooldown&&d<(boss?46:ranged?40:['hound','werewolf'].includes(n.role)?9:3.4)&&sight(n)){n.pending=n.role==='ashwing'&&!n.special?'breath':n.role==='abbess'&&!n.special?'tide':n.role==='harpy'&&!n.special?'scream':n.role==='hag'&&!n.special?'tide':boss&&!n.special?(n.phase===2?'nova':'charge'):n.role==='cantor'&&!n.special?'heal':['hound','werewolf'].includes(n.role)&&!n.special?'charge':'normal';if(n.pending!=='normal')n.special=boss?8:9;n.windup=['nova','breath','tide'].includes(n.pending)?1.1:n.pending==='charge'?.85:n.pending==='scream'?.9:.5;n.cooldown=boss?(n.phase===2?1.75:2.25):ranged?2.6:n.role==='hound'?1.5:1.75;n.cueAttack(ranged||boss?'mage':'sword')}
   }else{n.timer-=step;if(n.timer<=0){n.timer=4+rand()*3;n.target.copy(n.home).add(new T.Vector3((rand()-.5)*7,0,(rand()-.5)*7))}steer(n,n.target,.7,step,free,()=>true,.45)}n.update(step)
  }
  for(let i=warnings.length-1;i>=0;i--){const a=warnings[i];a.age+=dt;a.m.scale.setScalar(.85+a.age*.1);if(a.age>=1.25){if(Math.hypot(a.m.position.x-camera.position.x,a.m.position.z-camera.position.z)<a.r)onDamage(a.damage,'magic',a.owner);onSound('fireball');dispose(a.m);warnings.splice(i,1)}}
  for(let i=shots.length-1;i>=0;i--){const s=shots[i],old=s.m.position.clone();s.age+=dt;if(s.arrow)s.v.y-=2*dt;s.m.position.addScaledVector(s.v,dt);s.m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),s.v.clone().normalize());let hit=false,wall=false;const count=Math.max(1,Math.ceil(old.distanceTo(s.m.position)/.12));for(let j=1;j<=count;j++){const p=old.clone().lerp(s.m.position,j/count);if(blocked(p)){wall=true;break}if(p.distanceTo(camera.position)<.5){hit=true;break}}if(hit){const applied=onDamage(s.damage,s.arrow?'physical':'magic',s.owner);if(applied!==false&&s.slow)onSlow(s.slow)}if(hit||wall||s.age>5){dispose(s.m);shots.splice(i,1)}}
 }
 return {tick,clear,receive:(n,value)=>value*(n.block>0?.45:1),snapshot:()=>({time,shots:shots.map(s=>({position:s.m.position.toArray(),velocity:s.v.toArray(),age:s.age,damage:s.damage,arrow:s.arrow,owner:s.owner,slow:s.slow})),warnings:warnings.map(s=>({position:s.m.position.toArray(),age:s.age,r:s.r,damage:s.damage,owner:s.owner}))}),restore(s){clear();time=s?.time||0;for(const a of s?.shots||[]){const m=new T.Mesh(new T.IcosahedronGeometry(.2,1),new T.MeshBasicMaterial({color:0xc74373}));m.position.fromArray(a.position);root().add(m);shots.push({...a,m,v:new T.Vector3().fromArray(a.velocity)})}for(const a of s?.warnings||[]){warn(new T.Vector3().fromArray(a.position),a.r,a.damage,a.owner);warnings[warnings.length-1].age=a.age}}};
}
